import subprocess
import os
import tempfile
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp']
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def sanitize_filename(filename):
    """Remove path traversal attempts but allow special chars in names."""
    basename = os.path.basename(filename)
    # Strip null bytes
    basename = basename.replace('\x00', '')
    return basename

def get_image_dimensions(filepath):
    """Use ImageMagick identify to get image dimensions."""
    cmd = f"identify -format '%wx%h' {filepath}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=30)
    if result.returncode != 0:
        return None
    return result.stdout.strip()

def convert_image(filepath, output_format, resize=None):
    """Convert image using ImageMagick convert command."""
    output_path = filepath.rsplit('.', 1)[0] + '.' + output_format
    cmd = f"convert {filepath}"
    if resize:
        cmd += f" -resize {resize}"
    cmd += f" {output_path}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=60)
    if result.returncode != 0:
        raise RuntimeError(f"Conversion failed: {result.stderr}")
    return output_path

def generate_thumbnail(filepath, size='150x150'):
    """Generate thumbnail using ImageMagick."""
    thumb_path = filepath.rsplit('.', 1)[0] + '_thumb.' + filepath.rsplit('.', 1)[1]
    cmd = f"convert {filepath} -thumbnail {size} {thumb_path}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=30)
    if result.returncode != 0:
        raise RuntimeError(f"Thumbnail generation failed: {result.stderr}")
    return thumb_path

@app.route('/api/v1/images/upload', methods=['POST'])
def upload_image():
    if 'file' not in request.files:
        abort(400, 'No file provided')

    file = request.files['file']
    filename = sanitize_filename(file.filename)

    if not filename:
        abort(400, 'Invalid filename')

    ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''
    if ext not in ALLOWED_FORMATS:
        abort(400, f'Format not allowed. Use: {ALLOWED_FORMATS}')

    # Check file size
    file.seek(0, 2)
    size = file.tell()
    file.seek(0)
    if size > MAX_FILE_SIZE:
        abort(400, 'File too large')

    # Save to temp directory
    upload_dir = tempfile.mkdtemp(prefix='imgproc_')
    filepath = os.path.join(upload_dir, filename)
    file.save(filepath)

    # Get dimensions
    dimensions = get_image_dimensions(filepath)

    # Generate thumbnail
    try:
        thumb_path = generate_thumbnail(filepath)
    except RuntimeError as e:
        thumb_path = None

    return jsonify({
        'filename': filename,
        'dimensions': dimensions,
        'thumbnail': os.path.basename(thumb_path) if thumb_path else None
    })

@app.route('/api/v1/images/convert', methods=['POST'])
def convert():
    data = request.get_json()
    if not data or 'source' not in data or 'format' not in data:
        abort(400, 'Missing source or format')

    source = data['source']
    output_format = data['format'].lower()
    resize = data.get('resize', None)

    if output_format not in ALLOWED_FORMATS:
        abort(400, f'Format not allowed. Use: {ALLOWED_FORMATS}')

    # Validate resize parameter format
    if resize and not all(c in '0123456789x%!' for c in resize):
        abort(400, 'Invalid resize parameter')

    source_path = os.path.join('/var/lib/imgproc/uploads', sanitize_filename(source))
    if not os.path.exists(source_path):
        abort(404, 'Source file not found')

    try:
        output_path = convert_image(source_path, output_format, resize)
    except RuntimeError as e:
        abort(500, str(e))

    return jsonify({'output': os.path.basename(output_path)})

if __name__ == '__main__':
    os.makedirs('/var/lib/imgproc/uploads', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
